<?php
$subjects=$db->query("SELECT id,name,grade_level FROM subjects WHERE status='active' ORDER BY name")->fetchAll();$classes=$db->query("SELECT id,name FROM classes WHERE status='active' ORDER BY name")->fetchAll();
$edit=null;if(isset($_GET['edit'])){$stmt=$db->prepare('SELECT * FROM materials WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}$showForm=isset($_GET['create'])||$edit;
$subjectFilter=(int)($_GET['subject_id']??0);$sql="SELECT m.*,s.name subject_name,c.name class_name,(SELECT COUNT(*) FROM questions q WHERE q.material_id=m.id) question_count FROM materials m JOIN subjects s ON s.id=m.subject_id LEFT JOIN classes c ON c.id=m.class_id";$params=[];if($subjectFilter){$sql.=' WHERE m.subject_id=?';$params[]=$subjectFilter;}$sql.=' ORDER BY m.updated_at DESC';$stmt=$db->prepare($sql);$stmt->execute($params);$materials=$stmt->fetchAll();
?>
<div class="section-title"><div><h2>Materi pembelajaran</h2><p>Materi menjadi sumber jadwal, jurnal, dan generator soal.</p></div><a class="btn btn-primary" href="<?= url('materials',['create'=>1]) ?>"><?= icon('plus',17) ?> Tambah materi</a></div>
<?php if($showForm): ?><section class="card"><div class="card-header"><div><h2><?= $edit?'Edit':'Tambah' ?> materi</h2><p>Gunakan kalimat yang jelas agar generator soal dapat mengenali istilah penting.</p></div></div><div class="card-body"><form method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="save_material"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><input type="hidden" name="existing_attachment" value="<?= e($edit['attachment_path']??'') ?>"><div class="form-grid"><div class="form-group"><label>Mata pelajaran *</label><select class="form-control" name="subject_id" required><option value="">Pilih mata pelajaran</option><?php foreach($subjects as $item): ?><option value="<?= $item['id'] ?>" <?= selected($edit['subject_id']??'', $item['id']) ?>><?= e($item['name'].' • '.$item['grade_level']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Kelas tujuan</label><select class="form-control" name="class_id"><option value="">Semua kelas</option><?php foreach($classes as $item): ?><option value="<?= $item['id'] ?>" <?= selected($edit['class_id']??'', $item['id']) ?>><?= e($item['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Bab atau topik</label><input class="form-control" name="chapter" placeholder="Bab 1 • Sistem Pernapasan" value="<?= e($edit['chapter']??'') ?>"></div><div class="form-group"><label>Judul materi *</label><input class="form-control" name="title" required value="<?= e($edit['title']??'') ?>"></div><div class="form-group full"><label>Tujuan pembelajaran</label><textarea class="form-control" name="learning_objective" rows="3"><?= e($edit['learning_objective']??'') ?></textarea></div><div class="form-group full"><label>Isi materi *</label><textarea class="form-control" name="content" required rows="12" placeholder="Tuliskan materi lengkap. Gunakan beberapa kalimat definisi dan istilah penting."><?= e($edit['content']??'') ?></textarea><span class="help-text">Generator memakai teks ini. Materi yang terlalu singkat atau hanya berupa daftar akan menghasilkan soal yang lemah.</span></div><div class="form-group"><label>Estimasi waktu mengajar</label><input class="form-control" type="number" min="0" name="estimated_minutes" value="<?= e((string)($edit['estimated_minutes']??90)) ?>"></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><option value="planned" <?= selected($edit['status']??'planned','planned') ?>>Direncanakan</option><option value="in_progress" <?= selected($edit['status']??'','in_progress') ?>>Berjalan</option><option value="completed" <?= selected($edit['status']??'','completed') ?>>Selesai</option></select></div><div class="form-group"><label>Sumber referensi</label><input class="form-control" name="source_reference" value="<?= e($edit['source_reference']??'') ?>"></div><div class="form-group"><label>Lampiran maksimal 5 MB</label><input class="form-control" type="file" name="attachment" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.jpg,.jpeg,.png"><?php if(!empty($edit['attachment_path'])): ?><span class="help-text">Lampiran saat ini: <?= e(basename($edit['attachment_path'])) ?></span><?php endif; ?></div></div><div class="form-actions"><a class="btn btn-secondary" href="<?= url('materials') ?>">Batal</a><button class="btn btn-primary">Simpan materi</button></div></form></div></section><?php endif; ?>
<section class="card mt-3"><div class="card-header"><div><h2>Daftar materi</h2><p><?= count($materials) ?> materi ditemukan</p></div><form class="filter-bar" method="get"><input type="hidden" name="page" value="materials"><select class="form-control" name="subject_id"><option value="">Semua mata pelajaran</option><?php foreach($subjects as $item): ?><option value="<?= $item['id'] ?>" <?= selected($subjectFilter,$item['id']) ?>><?= e($item['name']) ?></option><?php endforeach; ?></select><button class="btn btn-secondary btn-sm">Filter</button><div class="search-box"><?= icon('search',17) ?><input class="form-control" placeholder="Cari materi..." data-filter-table="#material-table"></div></form></div><div class="table-wrap"><table class="data-table" id="material-table"><thead><tr><th>Materi</th><th>Mata pelajaran</th><th>Durasi</th><th>Soal</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($materials as $item): ?><tr><td><strong><?= e($item['title']) ?></strong><div class="muted text-sm"><?= e($item['chapter']?:'Tanpa bab') ?><?= $item['class_name']?' • '.e($item['class_name']):'' ?></div><?php if($item['attachment_path']): ?><a class="text-sm" href="<?= e($item['attachment_path']) ?>" target="_blank">Buka lampiran</a><?php endif; ?></td><td><?= e($item['subject_name']) ?></td><td><?= (int)$item['estimated_minutes'] ?> menit</td><td><?= (int)$item['question_count'] ?></td><td><?= status_badge($item['status']) ?></td><td><div class="actions"><a class="btn btn-warning btn-sm" href="<?= url('generator',['material_id'=>$item['id']]) ?>"><?= icon('sparkles',14) ?></a><a class="btn btn-secondary btn-sm" href="<?= url('materials',['edit'=>$item['id']]) ?>"><?= icon('edit',14) ?></a><form method="post" data-confirm="Hapus materi dan lampirannya? Soal atau jadwal terkait dapat mencegah penghapusan."><?= csrf_field() ?><input type="hidden" name="action" value="delete_material"><input type="hidden" name="id" value="<?= $item['id'] ?>"><button class="btn btn-danger btn-sm"><?= icon('trash',14) ?></button></form></div></td></tr><?php endforeach; ?><?php if(!$materials): ?><tr><td colspan="6"><div class="empty-state"><h3>Belum ada materi</h3><p>Tambahkan materi untuk menghubungkannya ke jadwal dan membuat soal.</p></div></td></tr><?php endif; ?></tbody></table></div></section>
